import { useId, type ReactNode } from 'react';
import { useControllableState } from '../../../primitives/use-controllable-state';
import './switch.css';

export interface SwitchProps {
  /** Visible label, said together with the state ("Show depth contours, on"). */
  label: ReactNode;
  /** Extra detail under the label. */
  description?: ReactNode;
  checked?: boolean;
  defaultChecked?: boolean;
  onCheckedChange?: (checked: boolean) => void;
  disabled?: boolean;
  /** Submit with a form under this name, as "on" when checked. */
  name?: string;
  value?: string;
  /** Put the switch before the label instead of after it. */
  labelPosition?: 'start' | 'end';
  className?: string;
}

/**
 * An on/off setting that takes effect at once. Follows the WAI-ARIA switch pattern: a
 * button with `role="switch"` and `aria-checked`. The thumb carries a mark when on, so the
 * state never relies on colour.
 */
export function Switch({
  label,
  description,
  checked: checkedProp,
  defaultChecked = false,
  onCheckedChange,
  disabled = false,
  name,
  value = 'on',
  labelPosition = 'end',
  className,
}: SwitchProps) {
  const [checked, setChecked] = useControllableState({
    value: checkedProp,
    defaultValue: defaultChecked,
    onChange: onCheckedChange,
  });
  const id = useId();
  const labelId = `${id}-label`;
  const descriptionId = `${id}-description`;

  const control = (
    <button
      id={id}
      type="button"
      role="switch"
      aria-checked={checked}
      aria-labelledby={labelId}
      aria-describedby={description ? descriptionId : undefined}
      disabled={disabled}
      className="atl-switch__control"
      onClick={() => setChecked((c) => !c)}
    >
      <span className="atl-switch__thumb" aria-hidden="true">
        <svg viewBox="0 0 12 12" width="12" height="12">
          <path d="M2.5 6.5 5 9l4.5-6" />
        </svg>
      </span>
    </button>
  );

  return (
    <div
      className={['atl-switch', className].filter(Boolean).join(' ')}
      data-label-position={labelPosition}
      data-disabled={disabled || undefined}
    >
      {labelPosition === 'start' ? control : null}
      <span className="atl-switch__text">
        {/* Clicking the label toggles too, like a native checkbox label. */}
        <label id={labelId} htmlFor={id} className="atl-switch__label">
          {label}
        </label>
        {description ? (
          <span id={descriptionId} className="atl-switch__description">
            {description}
          </span>
        ) : null}
      </span>
      {labelPosition === 'end' ? control : null}
      {name ? <input type="hidden" name={name} value={checked ? value : ''} /> : null}
    </div>
  );
}

@layer atlas.components {
  .atl-switch {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--space-m);
    min-height: var(--target-comfort);
  }

  .atl-switch[data-label-position='start'] {
    justify-content: flex-start;
  }

  .atl-switch__text {
    display: grid;
    min-width: 0;
  }

  .atl-switch__label {
    font-weight: 600;
    cursor: pointer;
  }

  .atl-switch[data-disabled] .atl-switch__label {
    cursor: not-allowed;
  }

  .atl-switch__description {
    color: var(--ink-soft);
    font-size: var(--step--1);
  }

  .atl-switch__control {
    --atl-switch-w: 46px;
    --atl-switch-h: 28px;
    --atl-switch-pad: 3px;
    position: relative;
    flex: none;
    width: var(--atl-switch-w);
    height: var(--atl-switch-h);
    padding: 0;
    border: 0;
    border-radius: var(--radius-round);
    background: var(--sea-1);
    box-shadow: inset 0 0 0 1px var(--edge);
    transition:
      background-color var(--dur-step) var(--ease-anchor),
      box-shadow var(--dur-step) var(--ease-anchor);
  }

  /* A larger invisible hit area, so the 28px track still gives a 44px target. */
  .atl-switch__control::before {
    content: '';
    position: absolute;
    inset: -8px -4px;
  }

  .atl-switch__control:hover:not(:disabled) {
    box-shadow: inset 0 0 0 1px var(--ink-soft);
  }

  .atl-switch__control[aria-checked='true'] {
    background: var(--ink);
    box-shadow: inset 0 0 0 1px var(--ink);
  }

  .atl-switch__control:disabled {
    cursor: not-allowed;
    opacity: 0.55;
  }

  .atl-switch__thumb {
    position: absolute;
    top: var(--atl-switch-pad);
    left: var(--atl-switch-pad);
    display: grid;
    place-items: center;
    width: calc(var(--atl-switch-h) - 2 * var(--atl-switch-pad));
    height: calc(var(--atl-switch-h) - 2 * var(--atl-switch-pad));
    border-radius: 50%;
    background: var(--ink-soft);
    color: var(--ink);
    transition:
      translate var(--dur-current) var(--ease-current),
      background-color var(--dur-step) var(--ease-anchor);
  }

  .atl-switch__control[aria-checked='true'] .atl-switch__thumb {
    translate: calc(var(--atl-switch-w) - var(--atl-switch-h)) 0;
    background: var(--sea-0);
  }

  .atl-switch__thumb svg {
    fill: none;
    stroke: currentColor;
    stroke-width: 1.75;
    stroke-linecap: round;
    stroke-linejoin: round;
    opacity: 0;
    scale: 0.6;
    transition:
      opacity var(--dur-step) var(--ease-anchor),
      scale var(--dur-step) var(--ease-anchor);
  }

  .atl-switch__control[aria-checked='true'] .atl-switch__thumb svg {
    opacity: 1;
    scale: 1;
  }

  @media (forced-colors: active) {
    .atl-switch__control {
      border: 1px solid ButtonText;
    }
    .atl-switch__thumb {
      background: ButtonText;
    }
    .atl-switch__control[aria-checked='true'] .atl-switch__thumb {
      background: Highlight;
    }
  }
}
